/* ~/.config/waybar/style.css */
/* Catppuccin Mocha */

/* ---- Catppuccin Mocha palette ---- */
@define-color rosewater #f5e0dc;
@define-color flamingo #f2cdcd;
@define-color pink #f5c2e7;
@define-color mauve #cba6f7;
@define-color red #f38ba8;
@define-color maroon #eba0ac;
@define-color peach #fab387;
@define-color yellow #f9e2af;
@define-color green #a6e3a1;
@define-color teal #94e2d5;
@define-color sky #89dceb;
@define-color sapphire #74c7ec;
@define-color blue #89b4fa;
@define-color lavender #b4befe;
@define-color text #cdd6f4;
@define-color subtext1 #bac2de;
@define-color overlay0 #6c7086;
@define-color surface2 #585b70;
@define-color surface1 #45475a;
@define-color surface0 #313244;
@define-color mantle #181825;
@define-color crust #11111b;

* {
  padding: 0;
  margin: 0;
  min-height: 0;
  border-radius: 0;
  border: none;
  text-shadow: none;
  transition: none;
  box-shadow: none;
}

window#waybar {
  color: @text;
  background: none;
  font-family: IosevkaTerm Nerd Font Propo, FontAwesome;
  font-size: 20px;
  /* Kept your larger font size */
  font-weight: 600;
}

/* ---- Motion reserved for the two states that genuinely need attention ---- */
@keyframes urgent-pulse {
  0% {
    background-color: @red;
    box-shadow: 0 0 0 1px alpha(@red, 0.6);
  }

  50% {
    background-color: @maroon;
    box-shadow: 0 0 6px 2px alpha(@red, 0.75);
  }

  100% {
    background-color: @red;
    box-shadow: 0 0 0 1px alpha(@red, 0.6);
  }
}

@keyframes critical-pulse {
  0% {
    opacity: 1;
  }

  50% {
    opacity: 0.55;
  }

  100% {
    opacity: 1;
  }
}

/* Base style for most modules - soft pills floating on the mocha surface */
#cpu,
#memory,
#pulseaudio,
#battery,
#clock,
#custom-cemu {
  background-color: @surface0;
  /* Elevated surface for the text part */
  border: 1px solid alpha(@overlay0, 0.35);
  /* Thin neutral edge, tinted per-module below */
  border-radius: 12px;
  padding-right: 10px;
  /* Padding for the text */
  box-shadow: 0 2px 5px alpha(@crust, 0.4);
  transition: all 200ms ease;
}

/* Text/icon accent color for each module */
#cpu {
  color: @peach;
  border-color: alpha(@peach, 0.4);
}

#memory {
  color: @blue;
  border-color: alpha(@blue, 0.4);
}

#pulseaudio {
  color: @sapphire;
  border-color: alpha(@sapphire, 0.4);
}

#pulseaudio.muted {
  color: @maroon;
  border-color: alpha(@maroon, 0.4);
}

#battery {
  color: @green;
  border-color: alpha(@green, 0.4);
}

#battery.critical {
  color: @red;
  border-color: alpha(@red, 0.5);
  animation-name: critical-pulse;
  animation-duration: 1.3s;
  animation-timing-function: ease-in-out;
  animation-iteration-count: infinite;
}

#battery.warning {
  color: @yellow;
  border-color: alpha(@yellow, 0.4);
}

#battery.charging,
#battery.plugged {
  color: @teal;
  border-color: alpha(@teal, 0.4);
}

#clock {
  color: @lavender;
  border-color: alpha(@lavender, 0.4);
}

/* Gentle hover feedback on the pills you can actually click */
#custom-cemu:hover,
#pulseaudio:hover {
  background-color: @surface1;
}

/* --- Special Modules --- */

/* Workspaces use their own styling */
#workspaces {
  background-color: alpha(@mantle, 0.9);
  border: 1px solid alpha(@surface2, 0.6);
  margin: 3px 5px;
  padding: 0px 8px;
  border-radius: 12px;
  box-shadow: 0 2px 6px alpha(@crust, 0.45);
}

#workspaces button {
  color: @subtext1;
  padding: 0 8px;
  margin: 0px 3px;
  transition: all 200ms ease;
}

#workspaces button:hover {
  color: @crust;
  background-color: @pink;
  border-radius: 9px;
}

#workspaces button.focused {
  color: @crust;
  background-color: @mauve;
  background-image: linear-gradient(135deg, @mauve, @pink);
  box-shadow: 0 0 10px alpha(@mauve, 0.55);
  border-radius: 9px;
}

#workspaces button.urgent {
  color: @crust;
  background-color: @red;
  border-radius: 9px;
  animation-name: urgent-pulse;
  animation-duration: 1.4s;
  animation-timing-function: ease-in-out;
  animation-iteration-count: infinite;
}

/* Mode, Window, and Tray get simpler, glassy backgrounds */
#mode,
#window,
#tray {
  background-color: alpha(@mantle, 0.9);
  border: 1px solid alpha(@surface2, 0.6);
  margin: 3px 5px;
  padding: 0px 12px;
  border-radius: 12px;
  box-shadow: 0 2px 6px alpha(@crust, 0.45);
}

/* Waybar tags the whole bar `.empty` when the workspace has no windows -
   use that to collapse the window-title capsule down to nothing */
window#waybar.empty #window {
  background-color: transparent;
  border-color: transparent;
  box-shadow: none;
  padding: 0;
  margin: 0;
  min-width: 0;
}

#window {
  color: @subtext1;
}

#mode {
  color: @flamingo;
}

tooltip {
  background-color: @mantle;
  border: 1px solid alpha(@mauve, 0.4);
  border-radius: 10px;
  padding: 6px;
}

tooltip label {
  color: @text;
}

#custom-cemu.on {
  color: @sky;
  border-color: alpha(@sky, 0.45);
}

#custom-cemu.off {
  color: @overlay0;
  border-color: alpha(@overlay0, 0.3);
}

